-- 1. Políticas permisivas para inserción y actualización
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_policies 
    WHERE tablename = 'lsb_signs_catalog' AND policyname = 'Inserción pública de catálogo LSB'
  ) THEN
    CREATE POLICY "Inserción pública de catálogo LSB" ON public.lsb_signs_catalog
      FOR INSERT TO public WITH CHECK (true);
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM pg_policies 
    WHERE tablename = 'lsb_signs_catalog' AND policyname = 'Actualización pública de catálogo LSB'
  ) THEN
    CREATE POLICY "Actualización pública de catálogo LSB" ON public.lsb_signs_catalog
      FOR UPDATE TO public USING (true);
  END IF;
END $$;

